## What the probes actually showed

I ran the validator and evaluator against hostile and malformed inputs. Results, verbatim:

| Input | Control requested | Result | Verdict |
|---|---|---|---|
| `__import__('os').system('id')` | — | Syntax error: `Unexpected character '_'` | Blocked, but **incidentally** — the character allowlist rejects `_`, `[`, `]` |
| `().__class__.__bases__[0].__subclasses__()` | — | Syntax error on `_` | Blocked, same incidental reason |
| `q+1` | `allow_variables=false` | **"Expression is syntactically valid."** | ❌ **Flag not enforced** |
| `sin(sin(sin(sin(sin(1)))))` | `max_depth=2` | **"Expression is syntactically valid."** | ❌ **Depth limit not enforced** |
| `1/0` · `sqrt(-1)` · `1e400*1e400` · `10^100000` | — | `result: null, type: "number", isError: false` | ❌ **Arithmetic fault reported as success** |
| `9^9^9^9` | — | `null`, `isError: false` | ❌ Silent overflow |
| `2^10000` | — | `null`, `isError: false` (but `2^1000` → `1.07e301`) | ❌ Silent ceiling |
| `z+1` | — | `isError: true` — "Undefined variable: z" | ✅ Errors correctly |
| `0^0` | — | `1` | Convention, undocumented |
| `batch_evaluate` | — | `handleBatchEvaluate is not a function` | ❌ Broken |

Three takeaways:

1. **Every failure mode returned `isError: false`.** Absence of a tool error does not mean the control worked. If your Python code branches on `isError`, `None` flows into your arithmetic and you get a `TypeError` at best, a silently wrong number at worst.
2. **The `allow_variables` and `max_depth` parameters are accepted and ignored.** This is the classic "parameter that looks like a policy" antipattern — a caller *believes* it disabled variables. Do not treat that validator as a security boundary.
3. **`^` is exponentiation here; in Python `^` is XOR and `**` is power.** If any code path ever routes the same string to `eval`, `2^3` silently returns `1` instead of `8`. That's a correctness-to-security crossover.

Also: named variables persist globally across evaluations (`q` set in one call resolved in the next), and `detailed`/`show_ast` were ignored. Shared mutable evaluator state is a cross-request data-leak channel in a multi-tenant service.

## The fix: allowlist the AST, never the string

String denylists lose. Build the policy on the parsed tree, and make every arithmetic fault a typed exception.

```python
import ast, math
from dataclasses import dataclass

class ExpressionError(Exception):
    def __init__(self, code: str, detail: str = ""):
        self.code = code            # stable, loggable reason code
        super().__init__(f"{code}: {detail}")

@dataclass(frozen=True)
class Limits:
    max_chars: int = 256
    max_nodes: int = 100
    max_depth: int = 16         # ENFORCED, unlike the probe tool
    max_power: int = 512        # cap on |exponent|
    max_magnitude: float = 1e100

FUNCS = {
    "abs": abs, "min": min, "max": max, "round": round,
    "sqrt": math.sqrt, "log": math.log, "exp": math.exp,
    "sin": math.sin, "cos": math.cos, "tan": math.tan,
    "floor": math.floor, "ceil": math.ceil,
}
_ARITY = {"abs": 1, "round": 1, "sqrt": 1, "log": 1, "exp": 1,
          "sin": 1, "cos": 1, "tan": 1, "floor": 1, "ceil": 1,
          "min": 2, "max": 2}

_BINOPS = {ast.Add: lambda a, b: a + b, ast.Sub: lambda a, b: a - b,
           ast.Mult: lambda a, b: a * b, ast.Div: lambda a, b: a / b,
           ast.FloorDiv: lambda a, b: a // b, ast.Mod: lambda a, b: a % b}
_UNARY = {ast.UAdd: lambda a: +a, ast.USub: lambda a: -a}

# Everything NOT in this set is rejected by omission — the safe direction.
_ALLOWED = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant,
            ast.Call, ast.Load, *_BINOPS, *_UNARY, ast.Pow)


def _check(node, depth=0, limits=Limits(), budget=None):
    if budget is None:
        budget = [limits.max_nodes]
    if depth > limits.max_depth:
        raise ExpressionError("DEPTH_EXCEEDED", f"depth {depth}")
    budget[0] -= 1
    if budget[0] < 0:
        raise ExpressionError("NODE_BUDGET_EXCEEDED")

    # Structural allowlist. ast.Attribute/Subscript/Name/Lambda/Comprehension/
    # JoinedStr/Starred/Await/Yield all fall through to the rejection below.
    if not isinstance(node, _ALLOWED):
        raise ExpressionError("NODE_NOT_ALLOWED", type(node).__name__)

    if isinstance(node, ast.Constant):
        if not isinstance(node.value, (int, float)) or isinstance(node.value, bool):
            raise ExpressionError("CONSTANT_NOT_ALLOWED", repr(node.value))
        return

    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name):
            raise ExpressionError("CALL_TARGET_NOT_ALLOWED")   # kills obj.method()
        name = node.func.id
        if name not in FUNCS:
            raise ExpressionError("FUNCTION_NOT_ALLOWED", name)
        if name.startswith("__") or "__" in name:
            raise ExpressionError("DUNDER_REJECTED", name)
        if node.keywords:
            raise ExpressionError("KWARGS_NOT_ALLOWED", name)
        if len(node.args) != _ARITY[name]:
            raise ExpressionError("ARITY_MISMATCH", f"{name} expects {_ARITY[name]}")

    for child in ast.iter_child_nodes(node):
        _check(child, depth + 1, limits, budget)


def _eval(node, limits):
    if isinstance(node, ast.Expression):
        return _eval(node.body, limits)
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.UnaryOp):
        return _UNARY[type(node.op)](_eval(node.operand, limits))
    if isinstance(node, ast.BinOp):
        left, right = _eval(node.left, limits), _eval(node.right, limits)
        if isinstance(node.op, ast.Pow):
            if abs(right) > limits.max_power:
                raise ExpressionError("POWER_EXCEEDED", f"exp={right}")
            if abs(left) > 1 and right * math.log10(abs(left)) > 100:
                raise ExpressionError("POWER_EXCEEDED", "magnitude estimate")
            return left ** right
        return _BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.Call):
        return FUNCS[node.func.id](*(_eval(a, limits) for a in node.args))
    raise ExpressionError("NODE_NOT_ALLOWED", type(node).__name__)


def safe_eval(text: str, limits: Limits = Limits()) -> float:
    if not isinstance(text, str):
        raise ExpressionError("NOT_A_STRING", type(text).__name__)
    if len(text) > limits.max_chars:
        raise ExpressionError("INPUT_TOO_LONG", f"{len(text)} > {limits.max_chars}")
    if "\x00" in text:
        raise ExpressionError("NUL_BYTE")

    try:
        tree = ast.parse(text, mode="eval")   # parse, do NOT eval
    except SyntaxError as exc:
        raise ExpressionError("SYNTAX_ERROR", str(exc.msg)) from exc

    _check(tree, limits=limits)               # policy before execution

    try:
        value = _eval(tree, limits)
    except ExpressionError:
        raise
    except ZeroDivisionError as exc:
        raise ExpressionError("DIVISION_BY_ZERO") from exc     # not None
    except OverflowError as exc:
        raise ExpressionError("OVERFLOW") from exc
    except (ValueError, TypeError) as exc:
        raise ExpressionError("DOMAIN_ERROR", str(exc)) from exc

    if not isinstance(value, (int, float)):
        raise ExpressionError("NON_NUMERIC_RESULT", type(value).__name__)
    if isinstance(value, float) and not math.isfinite(value):
        raise ExpressionError("NON_FINITE_RESULT", repr(value))
    if abs(value) > limits.max_magnitude:
        raise ExpressionError("MAGNITUDE_EXCEEDED", f"{value:.3g}")
    return value
```

Why each piece maps to a real risk:

- **`ast.parse(mode="eval")` then reject-by-omission** — no `eval()`/`exec()` ever touches the string. An unlisted node type cannot execute.
- **Rejecting `ast.Name` entirely** — that is how you *actually* enforce `allow_variables=False`. If you need variables, pass a per-call dict and read it explicitly; never a module global.
- **`depth` and node budget decremented before recursion** — this is what the probe tool's `max_depth` was supposed to do and didn't.
- **`_eval` runs only after `_check` returns** — validation and execution are separate phases, so a validation bug can't be bypassed by evaluation side effects.
- **Explicit `ExpressionError` with a reason code** — kills the `null`-as-success problem. Your caller can never mistake a fault for `0`.
- **Post-condition on `isfinite` and magnitude** — catches `inf`/`nan` that slip past `OverflowError` in float math.

If you don't want to own this, `simpleeval` and `asteval` are the vetted small alternatives — but check their CVE history and pin versions; both have had sandbox escapes. The strongest option of all is a **fixed formula registry**: store named formulas server-side (`("circle_area", "pi * r ** 2")`) and accept only an identifier plus numeric parameters. No user text is ever parsed.

## OWASP Top 10 mapping

| Risk | How it shows up here | Control in the code above |
|---|---|---|
| **A03 Injection** | `eval`/`exec` on user text → RCE via `__class__.__subclasses__()` | AST allowlist, `eval` never called |
| **A04 Insecure Design** | Trusting a validator's `allow_variables` flag that isn't enforced | Fail-closed by omission, not by flag |
| **A05 Security Misconfiguration** | Unbounded depth/exponent → parser stack overflow | `max_depth`, `max_nodes`, `max_power`, `max_chars` |
| **A06 Vulnerable Components** | Pinned-but-stale `sympy`/`numexpr` | SBOM + `pip-audit` in CI |
| **A09 Logging Failures** | Silent `null` with no audit trail | Typed reason codes per rejection, logged with actor + code |
| **A10 SSRF** | N/A unless expressions resolve remote symbols | No network primitives reachable from the tree |
| **API4:2023 Unrestricted Resource Consumption** (API Top 10) | `9^9^9^9` burns CPU/OOM | Power cap + per-user rate limit + wall-clock timeout |
| **CWE-369 / CWE-190** | Divide-by-zero, integer overflow | Explicit `DIVISION_BY_ZERO` / `OVERFLOW` |

Two things the table doesn't cover but you should add: run evaluation in a subprocess or thread with a hard timeout (Python can't reliably interrupt a C-level bignum op in-process), and strip untrusted expression text of control characters before it reaches your logs, or you've reintroduced log injection.

## Regression tests to lock this in

```python
import pytest
from yourmodule import safe_eval, ExpressionError

@pytest.mark.parametrize("payload,code", [
    ("__import__('os').system('id')", "SYNTAX_ERROR"),
    ("().__class__",                  "SYNTAX_ERROR"),
    ("().__class__.__bases__",        "SYNTAX_ERROR"),
    ("open('/etc/passwd')",           "FUNCTION_NOT_ALLOWED"),
    ("(1).bit_length()",              "CALL_TARGET_NOT_ALLOWED"),
    ("[x for x in ()]",               "NODE_NOT_ALLOWED"),
    ("lambda: 1",                     "NODE_NOT_ALLOWED"),
    ("1/0",                           "DIVISION_BY_ZERO"),
    ("sqrt(-1)",                      "DOMAIN_ERROR"),
    ("9^9^9^9",                       "SYNTAX_ERROR"),
    ("2**10000",                      "POWER_EXCEEDED"),
    ("x+1",                           "SYNTAX_ERROR"),   # variables off by default
    ("a" * 500,                       "INPUT_TOO_LONG"),
])
def test_rejects(payload, code):
    with pytest.raises(ExpressionError) as ei:
        safe_eval(payload)
    assert ei.value.code == code

def test_never_returns_none():
    for bad in ("1/0", "sqrt(-1)", "1e400*1e400", "log(0)"):
        with pytest.raises(ExpressionError):
            safe_eval(bad)

def test_no_global_state_leak():
    from yourmodule import safe_eval as f
    with pytest.raises(ExpressionError):
        f("q+1")
    assert f("1+1") == 2
```

The `test_never_returns_none` case is the direct regression test for what I observed — the evaluator returning `result: null` alongside `isError: false`.

## One caution about the tooling

The validator I probed reports syntax validity only and does not enforce the semantic controls it accepts — `allow_variables` and `max_depth` were both ignored, while `__import__` was blocked only because `_` isn't in the character set. Treat it as a syntax pre-check, not as the enforcement layer, and don't let its `isError: false` stand in for "safe." Your `safe_eval` should be the only thing between user text and execution, and it should fail closed when any limit is absent or unparsable.
